test('invoiceTotals sums discounts across multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, discountPercent: 10 },
      { qty: 1, unitPrice: 1000, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: subtotal 2000, discount 200
  // Line 2: subtotal 1000, discount 200
